262	        HttpStatus status = HttpStatus.BAD_REQUEST;
263	        BindingErrorsResponse errors = new BindingErrorsResponse();
264	        BindingResult bindingResult = e.getBindingResult();
265	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
266	        if (bindingResult.hasErrors()) {
