268	            List<String> errorFields = bindingResult.getFieldErrors().stream()
269	                .map(fieldError -> fieldError.getField())
270	                .distinct()
271	                .toList();
272	            detail.setProperty("errors", errorFields);
273	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
274	                .map(fieldError -> {
275	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
276	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
277	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
278	                        fieldError.getField(),
279	                        defaultMessage,
280	                        rejectedValue);
281	                    return new ValidationMessageDto(message)
282	                        .putAdditionalProperty("field", fieldError.getField())
283	                        .putAdditionalProperty("rejectedValue", rejectedValue)
284	                        .putAdditionalProperty("defaultMessage", defaultMessage);
285	                })
286	                .toList();
287	            logger.debug("Validation error at {} {}: {}",
288	                request.getMethod(),
289	                request.getRequestURI(),
290	                bindingResult.getFieldErrors());
291	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
292	            return ResponseEntity.status(status).body(detail);
293	        }
294	        return ResponseEntity.status(status).body(detail);
